    // Default is the default Context for builds.
    // It uses the GOARCH, GOOS, GOROOT, and GOPATH environment variables
    // if set, or else the compiled code's GOARCH, GOOS, and GOROOT.
    Context Default = defaultContext();
    gocpp::string defaultGOPATH()
    {
        auto env = "HOME"_s;
        if(mocklib::GOOS == "windows"_s)
        {
            env = "USERPROFILE"_s;
        }
        else
        if(mocklib::GOOS == "plan9"_s)
        {
            env = "home"_s;
        }
        if(auto home = os::Getenv(env); home != ""_s)
        {
            auto def = filepath::Join(home, "go"_s);
            if(filepath::Clean(def) == filepath::Clean(runtime::GOROOT()))
            {
                // Don't set the default GOPATH to GOROOT,
                // as that will trigger warnings from the go tool.
                return ""_s;
            }
            return def;
        }
        return ""_s;
    }

    gocpp::slice<gocpp::string> defaultToolTags;
    gocpp::slice<gocpp::string> defaultReleaseTags;
    Context defaultContext()
    {
        Context c = {};

        c.GOARCH = buildcfg::GOARCH;
        c.GOOS = buildcfg::GOOS;
        if(auto goroot = runtime::GOROOT(); goroot != ""_s)
        {
            c.GOROOT = filepath::Clean(goroot);
        }
        c.GOPATH = envOr("GOPATH"_s, defaultGOPATH());
        c.Compiler = runtime::Compiler;
        c.ToolTags = append(c.ToolTags, buildcfg::ToolTags);

        // our own private copy
        defaultToolTags = append(gocpp::slice<gocpp::string> {}, c.ToolTags);

        // Each major Go release in the Go 1.x series adds a new
        // "go1.x" release tag. That is, the go1.x tag is present in
        // all releases >= Go 1.x. Code that requires Go 1.x or later
        // should say "go:build go1.x", and code that should only be
        // built before Go 1.x (perhaps it is the stub to use in that
        // case) should say "go:build !go1.x".
        // The last element in ReleaseTags is the current release.
        for(auto i = 1; i <= goversion::Version; i++)
        {
            c.ReleaseTags = append(c.ReleaseTags, "go1."_s + strconv::Itoa(i));
        }

        // our own private copy
        defaultReleaseTags = append(gocpp::slice<gocpp::string> {}, c.ReleaseTags);

        auto env = os::Getenv("CGO_ENABLED"_s);
        if(env == ""_s)
        {
            env = defaultCGO_ENABLED;
        }
        //Go switch emulation
        {
            auto condition = env;
            int conditionId = -1;
            if(condition == "1"_s) { conditionId = 0; }
            else if(condition == "0"_s) { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    c.CgoEnabled = true;
                    break;
                case 1:
                    c.CgoEnabled = false;
                    break;
                default:
                    // cgo must be explicitly enabled for cross compilation builds
                    if(runtime::GOARCH == c.GOARCH && mocklib::GOOS == c.GOOS)
                    {
                        c.CgoEnabled = platform::CgoSupported(c.GOOS, c.GOARCH);
                        break;
                    }
                    c.CgoEnabled = false;
                    break;
            }
        }

        return c;
    }

    gocpp::string envOr(gocpp::string name, gocpp::string def)
    {
        auto s = os::Getenv(name);
        if(s == ""_s)
        {
            return def;
        }
        return s;
    }

